import numpy as np
from scipy.linalg import svd as scipy_svd

def solve(problem):
    A = problem['matrix']
    U, s, Vh = scipy_svd(A, full_matrices=False, lapack_driver='gesdd', overwrite_a=False, check_finite=False)
    return {'U': U, 'S': s, 'V': Vh.T}

import numpy as np
from scipy.linalg.lapack import dsyevd

def solve(problem):
    A = np.ascontiguousarray(problem, dtype=np.float64)
    w, v, info = dsyevd(A, compute_v=1, lower=1)
    if info != 0:
        w, v = np.linalg.eigh(A)
    return (w[::-1].tolist(), v[:, ::-1].T.tolist())

import numpy as np
from scipy.linalg import expm

def solve(problem):
    A = np.ascontiguousarray(problem['matrix'], dtype=np.float64)
    expA = expm(A)
    return {'exponential': expA}
